package docker

// serverBootstrapScript runs only filesystem repair and package setup as root.
// Installers and Java then run as the panel's UID/GID, so generated files remain
// editable by the panel. The main entry script is passed as $1, not interpolated.
const serverBootstrapScript = `set -eu

if [ "$(id -u)" = "0" ] && [ "${MCM_UID:?missing MCM_UID}" != "0" ]; then
  switch_user=""
  packages=""
  if command -v su-exec >/dev/null 2>&1; then
    switch_user="su-exec"
  elif command -v gosu >/dev/null 2>&1; then
    switch_user="gosu"
  elif command -v apk >/dev/null 2>&1; then
    switch_user="su-exec"
    packages="su-exec"
  elif command -v apt-get >/dev/null 2>&1; then
    switch_user="gosu"
    packages="gosu"
  else
    echo "Cannot run Minecraft as MCM_UID: install su-exec or gosu in the server image." >&2
    exit 1
  fi

  # BuildTools needs git. Install it before dropping privileges; the selected
  # Spigot/Bukkit runtime image already provides the JDK.
  case "${SERVER_TYPE:-}" in
    spigot|bukkit|craftbukkit)
      if ! command -v git >/dev/null 2>&1; then
        packages="$packages git"
      fi
      ;;
  esac

  if [ -n "$packages" ]; then
    if command -v apk >/dev/null 2>&1; then
      apk add --no-cache $packages
    elif command -v apt-get >/dev/null 2>&1; then
      apt-get update
      apt-get install -y --no-install-recommends $packages
    else
      echo "Cannot install required server tools: no supported package manager found." >&2
      exit 1
    fi
  fi

  # This also repairs files generated by older root-running containers.
  chown -R "${MCM_UID}:${MCM_GID:?missing MCM_GID}" /data
  export HOME=/data
  exec "$switch_user" "${MCM_UID}:${MCM_GID}" sh -c "$1"
fi

exec sh -c "$1"
`
